bool UHaivenBlueprintContracts::ParseAccountIdentityLinkFailedV0(const FString& Json, FHaivenAccountIdentityLinkFailedV0& Value, FString& Error)
{
	Haiven::AccountIdentityLinkFailedV0 Parsed;
	std::string Problem;
	if (!Haiven::ContractsJson::FromJson(HaivenBlueprintDetail::ToUtf8(Json), Parsed, Problem))
	{
		Value = FHaivenAccountIdentityLinkFailedV0();
		Error = HaivenBlueprintDetail::FromUtf8(Problem);
		return false;
	}
	Value = Haiven::Blueprint::FromCpp(Parsed);
	Error.Reset();
	return true;
}

FString UHaivenBlueprintContracts::AccountIdentityLinkFailedV0ToJson(const FHaivenAccountIdentityLinkFailedV0& Value)
{
	if (!HaivenBlueprintDetail::CanConvertToCpp(Value)) return FString();
	return HaivenBlueprintDetail::FromUtf8(Haiven::ContractsJson::ToJson(Haiven::Blueprint::ToCpp(Value)));
}

