bool UHaivenBlueprintContracts::ParseNotificationListV0(const FString& Json, TArray<FHaivenNotificationListV0Item>& Value, FString& Error)
{
	Haiven::NotificationListV0 Parsed;
	std::string Problem;
	if (!Haiven::ContractsJson::FromJson(HaivenBlueprintDetail::ToUtf8(Json), Parsed, Problem))
	{
		Value = TArray<FHaivenNotificationListV0Item>();
		Error = HaivenBlueprintDetail::FromUtf8(Problem);
		return false;
	}
	Value.Reset(static_cast<int32>(Parsed.size()));
	for (const auto& Item : Parsed)
	{
		Value.Add(Haiven::Blueprint::FromCpp(Item));
	}
	Error.Reset();
	return true;
}

FString UHaivenBlueprintContracts::NotificationListV0ToJson(const TArray<FHaivenNotificationListV0Item>& Value)
{
	Haiven::NotificationListV0 Items;
	Items.reserve(Value.Num());
	for (const auto& Item : Value)
	{
		if (!HaivenBlueprintDetail::CanConvertToCpp(Item)) return FString();
		Items.push_back(Haiven::Blueprint::ToCpp(Item));
	}
	return HaivenBlueprintDetail::FromUtf8(Haiven::ContractsJson::ToJson(Items));
}

